mapper.select:
  		select r.reviewNo, r.grade,r.reviewcontent,r.reviewdate,m.memberNickname from review r
		left join member m on m.memberno = r.memberno
		where hotelno =#{hotelno}



		 	 select reviewNo,grade,reviewcontent,reviewdate,memberNickname,hotelno from 
  			  (
   			   select
    		  rownum rn,r.reviewNo,r.grade,r.reviewcontent,r.reviewdate,m.memberNickname,r.hotelno
     		  from review r
    		  left join member m on m.memberno = r.memberno
    		  where hotelno = #{hotelno}
    		  and rownum <= #{cri.pageNum} * #{cri.amount}
    		  order by reviewNo desc
   			  ) where rn > (#{cri.pageNum} -1) * #{cri.amount}

mapper.update:
update hotel_room set roomName=#{roomname}, roomPrice=#{roomprice}, bedNo=#{bedno}, infoRoom=#{infoRoom},
checkInDate=#{checkInDate}, checkOutDate=#{checkOutDate}
where roomNo=#{roomno}

mapper.select:
select reasonNo, hotelNo, reasonTitle, reasonContent, reasonImage, regDate
from hotel_reason
where reasonNo = #{reasonNo}

mapper.update:
update hotel_reason set reasonTitle = #{reasonTitle}, reasonContent = #{reasonContent},
reasonImage = #{reasonImage},
reasonNo = reasonNo where reasonNo = #{reasonNo}

mapper.select:
	select amenityNo, hotelNo, amenityName, amenityIcon, amenityType, amenityOrder, regDate
	from hotel_amenity
	where hotelNo = #{hotelNo}

	and amenityType = #{amenityType}

order by amenityOrder asc, amenityNo asc

select amenityNo, hotelNo, amenityName, amenityIcon, amenityType, amenityOrder, regDate
from hotel_amenity
where amenityNo = #{amenityNo}

mapper.update:
update hotel_amenity
set amenityName  = #{amenityName},
    amenityIcon  = #{amenityIcon},
    amenityType  = #{amenityType},
    amenityOrder = #{amenityOrder}
where amenityNo = #{amenityNo}
